type Style = { font: string; size: number; bold: boolean };
class Glyph { constructor(private style: Style) {} }

const pool = new Map<object, Glyph>();
function getGlyph(style: Style) {
  if (!pool.has(style)) pool.set(style, new Glyph(style));
  return pool.get(style)!;
}

// Version A
// single cache keyed by full request context
const globalCacheA = new Map<string, Character>();
function getCharA(keyedContext: string) {
  if (!globalCacheA.has(keyedContext)) globalCacheA.set(keyedContext, new Character(keyedContext));
  return globalCacheA.get(keyedContext)!;
}

// Version B
// cache of small immutable glyphs; render context passed per draw
const glyphPoolB = new Map<string, Glyph>();
function getGlyphB(intrinsicKey: string) {
  if (!glyphPoolB.has(intrinsicKey)) glyphPoolB.set(intrinsicKey, new Glyph(intrinsicKey));
  return glyphPoolB.get(intrinsicKey)!;
}
